const getYiGroupEnding = (group, hasTone1, hasTone3) => {
    if (group === 'GROUP2') return hasTone1 ? 'ေ့' : (hasTone3 ? 'ေး' : 'ေ');
    if (group === 'GROUP3') return hasTone1 ? 'ဲ့' : (hasTone3 ? 'ဲ' : 'ယ်');
    return hasTone1 ? 'ိ' : (hasTone3 ? 'ီး' : 'ီ');
};

const findYiGroupException = (sylsList, idx) => {
    const syl = sylsList[idx];
    if (!syl || !(syl.combined.includes('ည်') || syl.combined.includes('ဉ်'))) return null;
    for (let len = 4; len >= 1; len--) {
        for (let start = Math.max(0, idx - len + 1); start <= idx; start++) {
            if (start + len > sylsList.length) continue;
            const word = sylsList.slice(start, start + len).map(s => s.combined).join('');
            if (YI_GROUP_EXCEPTIONS[word]) return YI_GROUP_EXCEPTIONS[word];
        }
    }
    return null;
};

const getColumnName = (index) => {
    let colName = '';
    let temp = index;
    while (temp >= 0) {
        colName = String.fromCharCode(65 + (temp % 26)) + colName;
        temp = Math.floor(temp / 26) - 1;
    }
    return colName;
};

const getColumnIndex = (colName) => {
    let index = 0;
    for (let i = 0; i < colName.length; i++) {
        index = index * 26 + (colName.charCodeAt(i) - 64);
    }
    return index;
};

