  const combineCharacters = (keysArray) => {
    let rawStr = keysArray.join('').normalize('NFC');
    rawStr = rawStr.replace(/\u1037\u103A/g, '\u103A\u1037'); 
    rawStr = rawStr.replace(/\u1038\u103A/g, '\u103A\u1038'); 
    rawStr = rawStr.replace(/\u1037\u1036/g, '\u1036\u1037'); 
    return rawStr;
  };

  const segmentSyllables = (text) => {
      let normalized = text.replace(/့်/g, '့်');
      normalized = normalized.replace(/([၀-၉]+)/g, ' $1 ').trim();
      
      let rawSegments = [];
      let chunks = normalized.split(/\s+/).filter(Boolean);
      
      for (let chunk of chunks) {
          if (/^[၀-၉]+$/.test(chunk)) {
              rawSegments.push(chunk);
          } else {
              let subSegs = chunk.split(/(?<!\u1039)(?=[က-အဣ-ဪ၌-၏](?!\u103A|\u1039))/g).filter(Boolean);
              rawSegments.push(...subSegs);
          }
      }

      const dictKeys = Object.keys(dynamicStacked).sort((a,b) => b.length - a.length);
      let mergedDict = [];
      let i = 0;
      while (i < rawSegments.length) {
          let matched = false;
          for (let len = 4; len >= 1; len--) {
              if (i + len <= rawSegments.length) {
                  let candidate = rawSegments.slice(i, i + len).join('');
                  if (dictKeys.includes(candidate)) {
                      mergedDict.push(candidate);
                      i += len;
                      matched = true;
                      break;
                  }
              }
          }
          if (!matched) {
              mergedDict.push(rawSegments[i]);
              i++;
          }
      }
      let segments = mergedDict;

      let merged = [];
      for (let j = 0; j < segments.length; j++) {
          if (j > 0 && segments[j].startsWith('ည') && !segments[j].startsWith('ည်')) {
              let prev = merged[merged.length - 1];
              let hasTone = prev.includes('့') || prev.includes('း');
              let { vowel } = extractBaseAndVowel(prev);
              let isShortVowel = (vowel === 'ု' || vowel === 'ိ' || vowel === '');
              
              if (!hasTone && isShortVowel) {
                  merged[merged.length - 1] += segments[j];
                  continue;
              }
          }
          merged.push(segments[j]);
      }
      return merged;
  };

  const WA_MODIFIERS = [
      'န်', 'န်း', 'န့်', 'န့်',
      'မ်', 'မ်း', 'မ့်', 'မ့်', 
      'ံ', 'ံ့', 'ံး', 
      'တ်', 'ပ်'
  ];

  const splitSyllableIntoTwo = (sylString) => {
      let base = '';
      let modifier = '';
      for (let cluster of ALL_CLUSTERS) {
          if (sylString.startsWith(cluster)) {
              base = cluster;
              modifier = sylString.slice(cluster.length);
              break;
          }
      }
      if (!base) {
          base = sylString.charAt(0);
          modifier = sylString.slice(1);
      }

      if (base.includes('ွ') && WA_MODIFIERS.includes(modifier)) {
          base = base.replace('ွ', '');
          modifier = 'ွ' + modifier;
      }

      return { base, modifier };
  };

  const DECOMPOSITION_TOKENS = [
    ...VIRTUAL_KEYBOARD_CHARS,
    ...CONSONANT_GROUPS_DATA[0],
    ...CONSONANT_GROUPS_DATA[7],
    'ဣ','ဤ','ဥ','ဦ','ဦး','ဧ','ဩ','ဪ', '၌','၍','၎င်း','၏', 'ဉ'
  ].sort((a, b) => b.length - a.length);

  const decomposeWord = (word) => {
      let str = word;
      const tokens = [];
      while (str.length > 0) {
          let matched = false;
          for (let token of DECOMPOSITION_TOKENS) {
              if (str.startsWith(token)) {
                  tokens.push(token);
                  str = str.slice(token.length);
                  matched = true;
                  break;
              }
          }
          if (!matched) {
              tokens.push(str.charAt(0));
              str = str.slice(1);
          }
      }
      return tokens;
  };

  const getExpectedTypingSequence = (word) => {
      let tokens = decomposeWord(word);
      const eIndex = tokens.indexOf('ေ');
      if (eIndex > 0) {
          tokens.splice(eIndex, 1);
          tokens.unshift('ေ');
      }
      return tokens;
  };

